"""`.printsect/DEPS.md`: the graph as a page people read in an editor."""

from __future__ import annotations

from .graph import Graph
from .tree import TreeOptions, build_tree, render_tree


def render_markdown(graph: Graph) -> str:
    lines = [
        "# Build dependencies",
        "",
        "Generated by printsect from deps.json (`psect deps`) - do not edit.",
        f"Made {graph.generated} from `{graph.command}`.",
        "",
        f"{len(graph.final_outs())} outputs, {len(graph.archives)} archives, "
        f"{len(graph.objects)} objects, {len(graph.headers())} headers.",
        "",
        "## Tree",
        "",
        "```text",
        *render_tree(build_tree(graph, {}, TreeOptions(sources=True))),
        "```",
        "",
        "## Headers",
        "",
    ]
    users = {h: graph.roots_for_file(h) for h in sorted(graph.headers())}
    if not graph.headers_traced:
        lines.append("(not followed: deps.headers is false)")
    elif users:
        lines += ["| Header | Built into |", "|---|---|"]
        lines += [f"| {h} | {', '.join(sorted(r))} |" for h, r in users.items()]
    else:
        lines.append("(none found)")
    if graph.warnings:
        lines += ["", "## Warnings", "", *[f"- {w}" for w in graph.warnings]]
    return "\n".join(lines) + "\n"
